                 "balance": "37610.40",
                 "email": "teague.bell@quintworks.co",
                 "phone": "+1-628-555-0159", "tax_id": "755-14-2290"},
}

# Who holds which role. Staff are not customers, so they have no account
# record and their tenant scope is declared separately.
USER_ROLES = {
